solution.code:
def same_letters(a: str, b: str) -> bool:
    if len(a) != len(b):
        return False
    counts = {}
    for ch in a:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in b:
        left = counts.get(ch, 0) - 1
        if left < 0:
            return False
        counts[ch] = left
    return True
